 "content": "def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2]
    if not points:
        return out
    rows = sorted(r for r, _ in points)
    # Use the median row as the shared horizontal connector. For an even
    # number of points, choose the lower of the two central rows.
    spine_row = rows[(len(rows) - 1) // 2]
    min_col = min(c for _, c in points)
    max_col = max(c for _, c in points)
    for r, c in points:
        step = 1 if spine_row >= r else -1
        for rr in range(r, spine_row + step, step):
            if out[rr][c] == 0:
                out[rr][c] = 3
    for c in range(min_col, max_col + 1):
        if out[spine_row][c] == 0:
            out[spine_row][c] = 3
    return out

if __name__ == '__main__':
